import React from 'react';
import { useParams } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import Toast from '../components/Toast';
import useToast from '../hooks/useToast';

const Products = () => {
  const { id } = useParams();
  const { isDarkMode } = useTheme();
  const { toasts, removeToast } = useToast();

  return (
    <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-black dark:to-black">
      <div className="max-w-6xl mx-auto px-4 py-10">
        <div
          className={`rounded-3xl p-8 md:p-12 ${
            isDarkMode
              ? 'bg-gray-800/40 backdrop-blur-xl border border-white/10'
              : 'bg-white/70 backdrop-blur-xl border border-gray-200'
          } shadow-xl`}
        >
          <div className="max-w-2xl mx-auto text-center">
            <div className="w-16 h-16 mx-auto mb-6 rounded-2xl bg-gradient-to-br from-primary-500 to-secondary-500 flex items-center justify-center text-white shadow-lg">
              <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth={2}
                  d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4"
                />
              </svg>
            </div>

            <h1 className={`text-3xl md:text-4xl font-bold mb-3 ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              Products Page (Rebuild)
            </h1>
            <p className={`text-base md:text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
              Product cards, search, filters and categories have been removed. We’ll rebuild the Products page from scratch with a modern UX.
            </p>

            {id ? (
              <p className={`mt-5 text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                Route param detected: <span className="font-mono">{id}</span>
              </p>
            ) : null}
          </div>
        </div>
      </div>

      {toasts.map((toast) => (
        <Toast
          key={toast.id}
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          onClose={() => removeToast(toast.id)}
        />
      ))}
    </div>
  );
};

export default Products;
